def carry_settings(apps, schema_editor):
    """O tempo vivia em `settings["pdv_lock_minutes"]` (0 = não bloqueava): vira os dois campos."""
    Store = apps.get_model("starrp", "Store")
    for store in Store._base_manager.all():
        settings = dict(store.settings or {})
        if "pdv_lock_minutes" not in settings:
            continue
        minutes = int(settings.pop("pdv_lock_minutes") or 0)
        store.pdv_auto_lock = minutes > 0
        store.pdv_lock_minutes = min(max(minutes, 1), 120) if minutes else 5
        store.settings = settings
        store.save(update_fields=["pdv_auto_lock", "pdv_lock_minutes", "settings"])


